    // is_export не проверяется вовсе, а не просто не показывается.
    self_service: selfService,
    self_service_dropped: selfServiceDropped,
    // Витрины, чьи СТАТЬИ уехали автору. «Build materials» сверяет этот
    // список с тем, по каким объектам инвентарь реально пришёл, и называет
    // разницу: статья прочитана, состав полей не получен — про такую витрину
