    // у режима выгрузки фолбэк был, у поиска отчёта — нет.
    topic_kind_used: topicKind,
    report_url_found: reportUrlFound,
    dd_count: plan.dd.length,
    no_question: plan.no_question,
    router_error: routerError,
    router_raw: rawOut,
  },
}];

